var n=`0759-githeri`;var t=`world-0759`;var s=`KE`;var a=`eastern-africa`;var r=4;var o=573;var l={en:`Githeri`,ua:`Гітері`};var d={en:`Githeri is a Kenya classic prepared with kidney beans, fresh corn kernels, potato, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Гітері, страва кухні країни Кенія зі складниками: червона квасоля кідні, зерна свіжої кукурудзи, картопля, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`kidney-beans`,250,`g`],[`water`,700,`ml`]]},{en:`Drain soaked kidney beans, cover with fresh water, boil vigorously for at least 10 minutes, then continue cooking until completely tender.`,ua:`Злийте воду із замоченої квасолі, залийте свіжою, інтенсивно кип’ятіть щонайменше 10 хвилин, потім варіть до повної м’якості.`,t:[`boiling`],m:65,i:[[`water`,1200,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`fresh-corn-kernels`,320,`g`],[`potato`,250,`g`],[`yellow-onion`,180,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,17,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:n,id:t,country:`KE`,region:a,servings:4,minutes:573,title:l,text:d,steps:g};export{s as country,h as default,t as id,o as minutes,a as region,r as servings,n as slug,g as steps,d as text,l as title};